        if(messageId!=null && messageId!==''){confirmedMessage=required(messageId,'Gmail message ID');if(/^local-/i.test(confirmedMessage))conflict('A simulated message ID cannot confirm Gmail creation.','GMAIL_DRAFT_INVALID');}
