        if (!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(email)) invalid('Recipient email is invalid.');
        const finalSnapshot=finalizeIdentity===true?finalizeOutreachIdentity(snapshot,{
          firstName:recipientFirstName(contact),
