      if (!Array.isArray(ids) || !ids.length || ids.length>100 || ids.some(id=>typeof id!=='string' || !id)) invalid('Select between 1 and 100 explicit queue IDs.');
      const byId=new Map(repository.list().map(item=>[item.id,item]));
