}
export function assertResolvedMessage(...values) {
  if (values.some(value => /\{\{|\}\}/.test(String(value ?? '')))) {
    const error = new Error('Final message contains an unsupported or unresolved placeholder.');
    error.statusCode = 400;
    throw error;
  }
}

