} = {}) {
  const jobDescription = parseJobDescription(
    jobDescriptionText,
    jobDescriptionOverrides
  );

  const selectedInventory = selectCvsByPath(
    inventory,
    selectedCvPaths
  );

  const rankedCvs = rankCvCandidates(
    jobDescription,
    selectedInventory,
