 let editorHtml,invalid=false;
 try{editorHtml=item.bodyHtml?sanitizeSnapshotHtml(item.bodyHtml).html:String(item.bodyPlainText||'').split('\n').map(escapeHtml).join('<br>');}
 catch{editorHtml=String(item.bodyPlainText||'').split('\n').map(escapeHtml).join('<br>');invalid=true;}
 return {editVersion:messageEditVersion(item),editorHtml,canEditMessage:item.status==='new'&&!attempted&&!invalid,
  messageReadOnlyReason:invalid?'Stored HTML is invalid. Correct the reviewed letter and queue it again.':
   item.status!=='new'||attempted?'Recorded message snapshot. Local edits cannot update an existing Gmail draft or sent email; use Gmail and recorded history.':''};
}
export function createQueueMessageEditor({repository,env=process.env}){
 return {save({queueId,expectedVersion,bodyPlainText,bodyHtml}={}){
  if(typeof queueId!=='string'||!queueId||typeof expectedVersion!=='string'||!/^[a-f0-9]{64}$/.test(expectedVersion))fail('A queue ID and current message version are required.',400);
  const item=repository.getById(queueId);if(!item)fail('Queue item no longer exists.',404);
  if(item.status!=='new')fail('This message is no longer editable. Refresh the queue; do not retry its Gmail operation.');
  if(messageEditVersion(item)!==expectedVersion)fail('The saved message changed elsewhere. Refresh the queue and discard/review your local edit before saving.');
  if(typeof bodyHtml!=='string'||!bodyHtml.trim())fail('A formatted message is required.',400);
  const snapshot=snapshotMessage(bodyPlainText,bodyHtml,item.application?.jobAdvertLink||'');
  const draft=prepareDraftSnapshot({...item,...snapshot});
  const candidate=String(env.CANDIDATE_DISPLAY_NAME||'Vijay DAFAL').trim();
  if(!draft.recipient.firstname||!draft.bodyPlainText.startsWith(`Dear ${draft.recipient.firstname},`)||!draft.bodyPlainText.endsWith(candidate))fail('Keep the selected recipient greeting and configured candidate signoff.',400);
  if(typeof repository.updatePendingMessage!=='function')fail('Queue message editing is unavailable.',503);
  const saved=repository.updatePendingMessage({queueId,expectedVersion,...snapshot});
  return {saved:true,item:{...saved,...messagePresentation(saved)}};
 }};
}

import { parseJobDescription } from '../domain/job-description/parse-job-description.js';
import { scoreCvAgainstJd } from '../domain/cv/score-cv-against-jd.js';

export function recommendCvs({
  jobDescriptionText = '',
  cvs = [],
  overrides = {}
} = {}) {
  const jobDescription = parseJobDescription(jobDescriptionText, overrides);

  const rankedCvs = cvs
    .map((cv, originalIndex) => ({
      cv,
      originalIndex,
      assessment: scoreCvAgainstJd(jobDescription, cv)
    }))
    .sort((left, right) => {
      const scoreDifference = right.assessment.score - left.assessment.score;
      return scoreDifference || left.originalIndex - right.originalIndex;
    })
    .map(({ originalIndex, ...result }) => result);

  return {
    jobDescription,
    rankedCvs
  };
}

export function createRecruiterContact(input, { now = Date.now } = {}) {
  const firstName = clean(input.firstName);
  const lastName = clean(input.lastName);
  const linkedinUrl = clean(input.linkedinUrl);

  if (!firstName || !lastName) {
    throw new Error("A recruiter contact requires both a first and last name.");
  }

  if (!linkedinUrl) {
    throw new Error("A recruiter contact requires a LinkedIn profile URL.");
  }

  const timestamp = now();

  return {
    id: `contact_${crypto.randomUUID()}`,
    organisationId: clean(input.organisationId),
    firstName,
    lastName,
    fullName: `${firstName} ${lastName}`,
    role: clean(input.role),
    linkedinUrl: linkedinUrl.split("?")[0],
    emailDomain: clean(input.emailDomain) || null,
    emailCandidates: Array.isArray(input.emailCandidates)
      ? input.emailCandidates.map(clean).filter(Boolean)
      : [],
    selectedEmail: clean(input.selectedEmail) || null,
    emailSource: clean(input.emailSource) || null,
    source: clean(input.source) || "linkedin-visible",
    sourceUrl: clean(input.sourceUrl),
    verified: Boolean(input.verified),
    outreachStatus: "new",
    firstImportedAt: timestamp,
    lastImportedAt: timestamp
  };
}

export function isDuplicateContact(existing, incoming) {
  if (existing.linkedinUrl && incoming.linkedinUrl) {
    return normaliseUrl(existing.linkedinUrl) === normaliseUrl(incoming.linkedinUrl);
  }

  return (
    existing.fullName.toLowerCase() === incoming.fullName.toLowerCase() &&
    existing.emailDomain?.toLowerCase() === incoming.emailDomain?.toLowerCase()
  );
}

export function mergeRecruiterContact(existing, incoming) {
  const hasSelectedEmail = Boolean(clean(existing.selectedEmail));
  const hasEmailState = hasSelectedEmail ||
    (Array.isArray(existing.emailCandidates) &&
      existing.emailCandidates.length > 0);

  const isLinked =
    Array.isArray(existing.linkedApplicationReviewIds) &&
    existing.linkedApplicationReviewIds.length > 0;

  const protectEmailState =
    existing.emailDomainSource === "manual" ||
    (hasSelectedEmail &&
      (existing.verified === true || existing.emailSource !== "inferred")) ||
    (isLinked && hasEmailState);

  const refreshedEmailState = protectEmailState ? {} : {
    emailDomain: incoming.emailDomain || existing.emailDomain,
    emailCandidates: incoming.emailCandidates?.length
      ? incoming.emailCandidates
      : existing.emailCandidates,
    selectedEmail: incoming.selectedEmail || existing.selectedEmail,
    emailSource: incoming.emailSource || existing.emailSource
  };

  return {
    ...existing,
    ...refreshedEmailState,
    role: incoming.role || existing.role,
    sourceUrl: incoming.sourceUrl || existing.sourceUrl,
    lastImportedAt: incoming.lastImportedAt
  };
}


function clean(value) {
  return typeof value === "string" ? value.trim() : "";
}

function normaliseUrl(value) {
  return value.split("?")[0].replace(/\/$/, "").toLowerCase();
}

