import {createHash} from 'node:crypto';
const norm=v=>String(v||'').normalize('NFKC').toLowerCase().replace(/\s+/gu,' ').trim();
export function vacancyIdentity(form={}){
 const name=norm(form.organisationName),title=norm(form.jobTitle),location=norm(form.jobLocation||form.location);let employer=name?'name:'+name:'',url='',sourceId='';
 try{const u=new URL(String(form.organisationUrl||''));if(['http:','https:'].includes(u.protocol)&&!u.username&&!u.password){const host=u.hostname.toLowerCase().replace(/^www\./,'');if(host==='linkedin.com'||host.endsWith('.linkedin.com')){const company=/^\/company\/([^/]+)/i.exec(u.pathname);if(company)employer='linkedin-company:'+company[1].toLowerCase();}else employer='domain:'+host;}}catch{}
 try{const u=new URL(String(form.jobAdvertLink||''));if(['http:','https:'].includes(u.protocol)&&!u.username&&!u.password){u.hash='';u.hostname=u.hostname.toLowerCase();const host=u.hostname.replace(/^www\./,'');if(host==='linkedin.com'||host.endsWith('.linkedin.com')){const match=/\/jobs\/view\/(?:[^/]*-)?([0-9]+)\/?$/i.exec(u.pathname);const id=match?.[1]||u.searchParams.get('currentJobId');if(id&&/^[0-9]+$/.test(id))sourceId='linkedin:'+id;}for(const key of [...u.searchParams.keys()])if(/^utm_/i.test(key)||['gclid','fbclid','msclkid'].includes(key.toLowerCase()))u.searchParams.delete(key);u.searchParams.sort();url=u.href;}}catch{}
 const reference=norm(form.jobReference),keys=[];if(sourceId)keys.push('source:'+sourceId);if(employer&&reference)keys.push('reference:'+employer+':'+reference);if(url)keys.push('url:'+url);
 const primary=keys[0]||'description:'+createHash('sha256').update(JSON.stringify([employer,title,location,String(form.jobDescriptionText||'').trim()])).digest('hex');
 const advert=String(form.jobAdvertLink||'').trim(),legacy=createHash('sha256').update(advert||JSON.stringify([form.organisationName||'',form.organisationUrl||'',form.jobTitle||'',form.jobReference||'',form.jobDescriptionText||''])).digest('hex');
 return {primary,keys,sourceId,legacyKey:legacy,employer,title,location,advertUrl:url,reference,displayEmployer:String(form.organisationName||''),displayTitle:String(form.jobTitle||'')};
}
export function matchVacancy(a,b){if(a.sourceId&&b.sourceId&&a.sourceId!==b.sourceId){if(a.employer&&a.employer===b.employer&&a.title===b.title)return {level:'possible',reason:'Similar role but different source vacancy IDs'};return null;}const same=a.keys.filter(k=>b.keys.includes(k));if(same.length)return {level:'exact',reason:same[0].startsWith('source:')?'Same source vacancy ID':same[0].startsWith('reference:')?'Same stated advertiser and scoped reference':'Same canonical advert URL'};if(a.legacyKey&&a.legacyKey===b.legacyKey)return {level:'exact',reason:'Same stored application identity'};if(a.employer&&a.employer===b.employer&&a.title&&a.title===b.title&&(!a.location||!b.location||a.location===b.location))return {level:'possible',reason:'Same stated advertiser/title; vacancy identifiers differ or are missing'};return null;}

