  '{{firstname}}',
  '{{recipient}}',
  '{{role}}',
  '{{cvHighlights}}',
  '{{jdKeywords}}',
  '{{companyValues}}',
  '{{refinedCoverLetter}}',
  '{{atsScore}}',
