export function validateCoverLetter({
  plainText = '',
  richText = ''
} = {}) {
  const unresolved = [
    ...String(plainText).matchAll(/{{\s*([\w]+)\s*}}/g)
  ]
    .map((match) => match[1])
    .filter((token) => !allowedTokens.has(`{{${token}}}`));

  const filler = ['about, job, role', 'undefined', 'null'];

  const fillerMatches = filler.filter((phrase) =>
    String(plainText).toLowerCase().includes(phrase)
  );

  const wordCount = String(plainText)
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .length;

  const errors = [
    ...(unresolved.length
      ? [`Unresolved template tokens: ${unresolved.join(', ')}.`]
      : []),
    ...(fillerMatches.length
      ? [`Generic filler detected: ${fillerMatches.join(', ')}.`]
      : []),
    ...(!String(richText).includes('<a href=')
      ? ['The advert hyperlink is not embedded in rich text.']
      : [])
  ];

  return {
    valid: errors.length === 0,
    errors,
    wordCount
  };
}

import { normalize, overlap, unique } from '../shared/text-normalization.js';

const priorityScore = {
  'very-high': 10,
  high: 7,
  medium: 5,
  low: 2
};

function cvCorpus(cv) {
  return [
    cv.text,
    cv.role_name,
    cv.role_code,
    ...(cv.tags || []),
    ...(cv.use_cases || [])
  ].join(' ');
}

function suggestionsFor({ score, missingKeywords, scClearanceRequired }) {
  if (score >= 85) {
    return [];
  }

  return [
    `Add evidence for: ${
      missingKeywords.slice(0, 5).join(', ') ||
      'the highest-priority JD requirements'
    }.`,
    'Mirror the employer wording in the experience and skills sections where truthful.',
    scClearanceRequired
      ? 'State SC/security clearance status explicitly if current and verifiable.'
      : 'Add measurable delivery outcomes to the most relevant role.'
  ];
}

export function scoreCvAgainstJd(jobDescription, cv) {
  const cvText = cvCorpus(cv);
  const matchedKeywords = overlap(jobDescription.keywords, cvText);

  const missingKeywords = unique(
    jobDescription.keywords
      .filter((keyword) => !matchedKeywords.includes(normalize(keyword)))
  ).slice(0, 20);

  const keywordComponent = jobDescription.keywords.length
    ? (matchedKeywords.length / jobDescription.keywords.length) * 40
    : 0;

  const useCaseMatches = overlap(
    jobDescription.keywords,
    (cv.use_cases || []).join(' ')
  );

  const useCaseComponent = jobDescription.keywords.length
    ? (
      useCaseMatches.length /
      Math.max(1, Math.min(jobDescription.keywords.length, 5))
    ) * 30
    : 0;

  const roleName = cv.role_name || '';

  const roleCategory = normalize(jobDescription.role).includes(normalize(roleName)) ||
    normalize(roleName).includes(normalize(jobDescription.role))
    ? 20
    : overlap(jobDescription.seniority, roleName).length
      ? 10
      : 0;

  const priorityRecency = priorityScore[cv.priority] || 0;

  const score = Math.min(
    100,
    Math.round(
      keywordComponent +
      Math.min(30, useCaseComponent) +
      roleCategory +
      priorityRecency
    )
  );

  return {
    score,
    matchedKeywords,
    missingKeywords,
    suggestions: suggestionsFor({
      score,
      missingKeywords,
      scClearanceRequired: jobDescription.scClearanceRequired
    }),
    components: {
      keywordMatch: Math.round(keywordComponent),
      useCaseAlignment: Math.round(Math.min(30, useCaseComponent)),
      roleCategory,
      priorityRecency
    }
  };
}

import { scoreCvAgainstJd } from './score-cv-against-jd.js';

function candidatesFrom(inventory = {}) {
  return inventory.cv_inventory?.cvs || inventory.cvs || [];
}

function preferenceRank(roleCode, preferredRoleCodes) {
  const index = preferredRoleCodes.indexOf(roleCode);

  return index === -1
    ? preferredRoleCodes.length
    : index;
}

export function rankCvCandidates(
  jobDescription,
  inventory,
  preferredRoleCodes = []
) {
  const cvs = candidatesFrom(inventory);

  if (!cvs.length) {
    throw new Error('CV inventory contains no CV entries.');
  }

  return cvs
    .map((cv, originalIndex) => ({
      cv,
      ats: scoreCvAgainstJd(jobDescription, cv),
      originalIndex
    }))
    .sort((left, right) => {
      const scoreDifference = right.ats.score - left.ats.score;

      if (scoreDifference !== 0) {
        return scoreDifference;
      }

      const preferenceDifference =
        preferenceRank(left.cv.role_code, preferredRoleCodes) -
        preferenceRank(right.cv.role_code, preferredRoleCodes);

      if (preferenceDifference !== 0) {
        return preferenceDifference;
      }

      return left.originalIndex - right.originalIndex;
    })
    .map(({ originalIndex, ...candidate }) => candidate);
}

export function selectCv(
  jobDescription,
  inventory,
  preferredRoleCodes = []
) {
  const ranked = rankCvCandidates(
    jobDescription,
    inventory,
    preferredRoleCodes
  );

  return {
    bestCv: ranked[0].cv,
    alternativeCv: ranked[1]?.cv ?? null,
    ats: ranked[0].ats
  };
}

import { win32 as path } from 'node:path';

function candidatesFrom(inventory = {}) {
  return inventory.cv_inventory?.cvs || inventory.cvs || [];
}

function normalizedPath(value = '') {
  return path.resolve(String(value));
}

function createSyntheticCv(pathValue, index) {
  const filename = path.basename(pathValue) || pathValue;
  const folder = path.basename(path.dirname(pathValue)) || 'Selected CV';

  const roleName = `${folder} ${filename}`
    .replace(/\.(docx|pdf)$/i, '')
    .replace(/[_-]+/g, ' ')
    .trim();

  const tags = roleName
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((tag) => tag.length > 2);

  return {
    role_code: `CUSTOM-${index + 1}`,
    role_name: roleName,
    filename,
    folder,
    local_path: pathValue,
    tags,
    use_cases: [],
    priority: 'medium',
    recency: ''
  };
}

export function selectCvsByPath(inventory, selectedCvPaths = []) {
  if (!selectedCvPaths.length) {
    return inventory;
  }

  const cvs = candidatesFrom(inventory);
  const normalizedPaths = selectedCvPaths.map(normalizedPath);

  const selected = normalizedPaths.map((selectedPath, index) => {
    const existing = cvs.find(
      (cv) =>
        cv.local_path &&
        normalizedPath(cv.local_path) === selectedPath
    );

    return existing || createSyntheticCv(selectedPath, index);
  });

  return {
    ...inventory,
    cv_inventory: {
      ...(inventory?.cv_inventory || {}),
      cvs: selected
    }
  };
}

import { normalize, tokenize, unique } from '../shared/text-normalization.js';

const stopWords = new Set([
  'a', 'an', 'about', 'above', 'after', 'again', 'also', 'and', 'are',
  'as', 'at', 'be', 'been', 'being', 'below', 'but', 'can', 'could',
  'do', 'does', 'for', 'from', 'have', 'has', 'had', 'if', 'in', 'into',
  'is', 'it', 'its', 'job', 'join', 'me', 'more', 'of', 'on', 'or',
  'our', 'role', 'so', 'such', 'that', 'the', 'their', 'them', 'there',
  'these', 'this', 'those', 'through', 'to', 'under', 'using', 'us',
  'via', 'we', 'were', 'with', 'will', 'would', 'you', 'your'
]);

const allowedShortTerms = new Set([
  'uk', 'sc', 'dv', 'qa', 'ai', 'saas', 'safe'
]);

function cleanToken(value) {
  const cleaned = normalize(String(value || ''))
    .replace(/^[^a-z0-9]+|[^a-z0-9]+$/gi, '')
    .trim();

  if (!cleaned) {
    return '';
  }

  if (stopWords.has(cleaned)) {
    return '';
  }

  if (cleaned.length < 3 && !allowedShortTerms.has(cleaned)) {
    return '';
  }

  return cleaned;
}

function singularCandidate(value) {
  if (value.endsWith('ies') && value.length > 4) {
    return `${value.slice(0, -3)}y`;
  }

  if (
    value.endsWith('s') &&
    !value.endsWith('ss') &&
    !value.endsWith('us') &&
    value.length > 4
  ) {
    return value.slice(0, -1);
  }

  return '';
}

export function extractJobKeywords(text = '') {
  const cleanedTokens = unique(
    tokenize(String(text))
      .map(cleanToken)
      .filter(Boolean)
  );

  const available = new Set(cleanedTokens);
  const output = [];
  const claimedSingulars = new Set();

  for (const token of cleanedTokens) {
    const singular = singularCandidate(token);

    if (singular && available.has(singular)) {
      output.push({ pendingSingular: singular });
      claimedSingulars.add(singular);
      continue;
    }

    if (claimedSingulars.has(token)) {
      output.push(token);
      continue;
    }

    output.push(token);
  }

  return unique(
    output.map((item) => item.pendingSingular || item)
  );
}

