 const field=n=>form.elements.namedItem(n),mode=field('achievementMode'),code=field('achievementCvRoleCode'),hash=field('achievementSourceHash');
 const select=doc.getElementById('achievement-cv'),load=doc.getElementById('load-cv-achievements'),status=doc.getElementById('achievement-status'),list=doc.getElementById('achievement-options'),ids=doc.getElementById('achievement-id-fields');
 const preference=field('preferredRoleCodes'),roleList=doc.getElementById('preferred-role-list'),roleBox=doc.getElementById('preferred-role-choices'),fallback=doc.getElementById('preferred-role-fallback'),legacy=doc.querySelector('[data-legacy-highlights]');
 const savedKey='application-achievement-selection-v1';let busy=false,loaded=null,version=0;
