 async function api(url,payload){const r=await fetchImpl(url,payload===undefined?{cache:'no-store'}:{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok||data.ok!==true)throw new Error(data.error||'Evidence preparation unavailable.');return data;}
 function getSaved(){try{return JSON.parse(doc.defaultView.localStorage.getItem(savedKey)||'null');}catch{return null;}}
 function selected(){return [...list.querySelectorAll('input:checked')].map(e=>e.value);}
 function sync(){ids.replaceChildren();for(const id of selected()){const e=node('input');e.type='hidden';e.name='achievementIds';e.value=id;ids.appendChild(e);}try{doc.defaultView.localStorage.setItem(savedKey,JSON.stringify({roleCode:code.value,sourceHash:hash.value,ids:selected()}));}catch{}if(loaded)status.textContent=selected().length+' selected from '+loaded.roleCode+'. Only selected statements enter the letter.';}
 function reset(){loaded=null;list.replaceChildren();ids.replaceChildren();hash.value='';code.value=select.value;version++;try{doc.defaultView.localStorage.setItem(savedKey,JSON.stringify({roleCode:code.value,sourceHash:'',ids:[]}));}catch{}}
 select.addEventListener('change',()=>{reset();load.disabled=!select.value;status.textContent=select.value?'Load and review the CV before generating.':'No achievements selected; no achievement claims will be invented.';});
 function render(catalogue,restore){loaded=catalogue;code.value=catalogue.roleCode;hash.value=catalogue.sourceHash;list.replaceChildren();
  for(const x of catalogue.candidates){const card=node('article');card.className='achievement-card';const label=node('label'),check=node('input');check.type='checkbox';check.value=x.id;check.checked=restore.includes(x.id);check.setAttribute('aria-label',x.text);label.append(check,node('span',x.text));check.addEventListener('change',()=>{if(selected().length>12){check.checked=false;status.textContent='Choose at most twelve achievements.';return;}sync();});
   const signals=node('p','Method '+(x.signals.method?'present':'not stated')+'; measurement/number '+(x.signals.measurement?'present — review meaning':'not stated')+'; explicit duration '+(x.signals.timeframe?'present — review meaning':'not stated')+'.');signals.className='achievement-signals';const source=node('details');source.append(node('summary','View source context'),node('p',x.attribution),node('pre',x.context));card.append(label,signals,source);list.appendChild(card);}
  if(!catalogue.candidates.length)list.appendChild(node('p','No safe result statements identified. Nothing was invented. Choose another CV or improve the source CV truthfully, then reload.'));
