 load.addEventListener('click',async()=>{if(busy||!select.value)return;busy=true;load.disabled=true;const requestVersion=version,chosen=select.value,previousHash=hash.value;let restore=[];
  try{restore=JSON.parse(ids.dataset.savedIds||'[]');}catch{}const saved=getSaved();if(saved?.roleCode===chosen&&saved.sourceHash===previousHash)restore=saved.ids||restore;
