  for(const role of roles){const label=node('label'),check=node('input');check.type='checkbox';check.value=role.roleCode;check.checked=current.has(role.roleCode);label.append(check,node('span',role.roleCode+' — '+role.roleName));check.addEventListener('change',()=>{preference.value=[...roleList.querySelectorAll('input:checked')].map(e=>e.value).join(', ');preference.dispatchEvent(new Event('input',{bubbles:true}));});roleList.appendChild(label);const option=node('option',role.roleCode+' — '+role.roleName+(role.hasDocument?'':' (document not configured)'));option.value=role.roleCode;option.disabled=!role.hasDocument;select.appendChild(option);}
