 async function api(path,body){const r=await fetch('/api/application-intelligence/'+path,body?{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}:{cache:'no-store'});const v=await r.json();if(!r.ok||!v.ok)throw Error(v.error||'Application intelligence unavailable.');return v;}
 function p(parent,text){const el=document.createElement('p');el.textContent=text;parent.appendChild(el);return el;}
 async function run(fn){if(busy)return;busy=true;panel.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){status.textContent=e.message;}finally{busy=false;panel.querySelectorAll('button').forEach(b=>b.disabled=false);}}
 async function refresh(){const h=await api('history?'+new URLSearchParams({reviewId})),box=get('[data-ai-history]');box.replaceChildren();status.textContent=h.matchState==='no_match_in_available_records'?'No matching activity in available local records. This is not a claim that you have never applied.':h.summary.hasRecordedSubmission?'Previous user-recorded external submission found.':h.summary.hasConfirmedOutreach?'Previous confirmed outreach found; ATS submission is not established.':'Prior local activity found. Review its state before repeating work.';
  for(const r of h.records){const row=document.createElement('div');p(row,[r.matchLevel,r.kind,r.matchReason,r.date?new Date(r.date).toLocaleString():'Date unknown',r.recipient||r.channel||'',r.provenance].join(' · '));if(r.reference||r.note)p(row,[r.reference,r.note].filter(Boolean).join(' · '));if(r.reviewId){const a=document.createElement('a');a.href='/applications/'+encodeURIComponent(r.reviewId);a.textContent='Open previous saved application';row.appendChild(a);}if(r.kind==='submitted_external'){const b=document.createElement('button');b.type='button';b.textContent='Void incorrect manual record';b.addEventListener('click',()=>{if(window.confirm('Mark this local manual submission record as entered in error? Original audit record is retained.'))run(async()=>{await api('void-submission',{eventId:r.id,reason:'Entered in error',confirmed:true});await refresh();});});row.appendChild(b);}box.appendChild(row);}
  if(h.coverage.legacyRecordsWithLimitedMetadata)p(box,h.coverage.legacyRecordsWithLimitedMetadata+' legacy operation records have limited vacancy metadata. Coverage is not a full inbox/portal audit.');
  const data=await api('assessments?'+new URLSearchParams({reviewId})),list=get('[data-ai-assessments]');list.replaceChildren();for(const a of data.items){const row=document.createElement('details'),heading=document.createElement('summary');heading.textContent=[a.cvRoleCode,a.status,a.status==='captured'?a.coveragePercent+'% document keyword coverage · '+a.missingCount+' not found / '+a.termCount+' assessed':'CV text/version unavailable (not zero coverage)',a.createdAt].join(' · ');row.appendChild(heading);const content=document.createElement('div');row.appendChild(content);let loaded=false;row.addEventListener('toggle',()=>{if(!row.open||loaded)return;loaded=true;api('assessment?'+new URLSearchParams({reviewId,id:a.id})).then(({assessment:s})=>{p(content,'CV file SHA-256: '+(s.cvFileHash||'unknown'));p(content,'JD SHA-256: '+s.jdHash+' · scheme: '+s.scheme);p(content,'Not found in extracted text (not proof the person lacks these skills): '+s.missing.join(', '));const b=document.createElement('button');b.type='button';b.textContent='Delete this assessment snapshot';b.addEventListener('click',()=>{if(window.confirm('Delete this local assessment snapshot only? CV files and mail history are unchanged.'))run(async()=>{await api('delete-assessment',{id:a.id,reviewId,confirmed:true});await refresh();});});content.appendChild(b);}).catch(e=>{content.textContent=e.message;});});list.appendChild(row);}
