function dashboard(data,q){return `<!doctype html><html lang="en" class="review-workspace"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Saved applications</title><link rel="stylesheet" href="/application-review-controls.css"><link rel="stylesheet" href="/review-workspace.css"><script type="module" src="/review-workspace.js" nonce="__SCRIPT_NONCE__"></script><script type="module" src="/saved-application-delete.js" nonce="__SCRIPT_NONCE__"></script></head><body><main><h1>Saved applications</h1><p><a href="/">New application</a> · <a href="/outreach-queue">Outreach queue</a></p><p>Resume opens saved data without repeating research, paid polishing or Gmail actions. Local cost estimates may refresh. These are prepared application records, not proof of ATS submission. Old in-memory reviews are not automatically migrated; existing outreach remains in the queue/history.</p><form method="get" action="/applications"><input name="q" value="${escape(q)}" aria-label="Search saved applications" placeholder="Employer, role or subject"><button>Search</button></form><p>${data.total} application(s) · page ${data.page}/${data.pages}</p><div class="application-list-scroll"><table><thead><tr><th>Employer</th><th>Role</th><th>Subject</th><th>CV</th><th>Advert</th><th>Saved at</th><th>Action</th></tr></thead><tbody>${data.items.map(r=>`<tr><td>${escape(r.organisation)}</td><td>${escape(r.jobTitle)}</td><td>${escape(r.subject)}</td><td>${escape(r.cvCode)}</td><td>${advert(r)}</td><td>${escape(r.updatedAt||'')}</td><td><a href="/applications/${encodeURIComponent(r.id)}">Resume</a> <button type="button" data-delete-saved-review="${escape(r.id)}">Delete saved application</button></td></tr>`).join('')||'<tr><td colspan="7">No saved applications yet. Prepare a new application to start.</td></tr>'}</tbody></table></div><p>${data.page>1?`<a href="/applications?q=${encodeURIComponent(q)}&page=${data.page-1}">Previous</a>`:''} ${data.page<data.pages?`<a href="/applications?q=${encodeURIComponent(q)}&page=${data.page+1}">Next</a>`:''}</p></main></body></html>`;}
async function body(req){if(!String(req.headers['content-type']||'').startsWith('application/json'))throw Object.assign(new Error('JSON required.'),{statusCode:415});const chunks=[];let size=0;for await(const chunk of req){size+=chunk.length;if(size>1024*1024)throw Object.assign(new Error('Review save exceeds 1 MiB.'),{statusCode:413});chunks.push(Buffer.isBuffer(chunk)?chunk:Buffer.from(chunk));}try{return JSON.parse(Buffer.concat(chunks).toString('utf8'));}catch{throw Object.assign(new Error('Valid JSON required.'),{statusCode:400});}}
export function createApplicationReviewHandler({store,renderReview,sendJson,sendHtml,sendText,applicationPackExporter=null,letterUpdates=null}){
 return async(req,res,url)=>{
  const method=req.method||'GET',route=url.pathname,api=/^\/api\/application-reviews(?:\/([A-Za-z0-9_-]{1,100}))?$/.exec(route),resume=/^\/applications\/([A-Za-z0-9_-]{1,100})$/.exec(route);
  const asset=['/workspace-review-v2.js','/review-flow-view.js','/contact-workflow-policy.js','/contact-history-display.js','/review-workspace.css','/review-workspace.js','/application-review-controls.js','/application-review-controls.css','/application-export-controls.js','/unsent-letter-update-controls.js'].includes(route);
