  try{
   const origin=req.headers.origin;if((origin&&origin!==`http://${req.headers.host}`&&origin!==`https://${req.headers.host}`)||req.headers['sec-fetch-site']==='cross-site'){sendJson(res,403,{ok:false,error:'Cross-origin application access is not allowed.'});return true;}
   if(asset){const code=await readFile(new URL('.'+route,import.meta.url),'utf8');sendText(res,200,code,{'content-type':route.endsWith('.css')?'text/css; charset=utf-8':'text/javascript; charset=utf-8','cache-control':'no-store'});return true;}
   if(method==='POST'&&route.startsWith('/api/application-reviews/unsent-update/')){if(!req.headers.origin||!['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket?.remoteAddress)){sendJson(res,403,{ok:false,error:'Local same-origin update required.'});return true;}if(!letterUpdates)throw Object.assign(new Error('Unsent updates unavailable.'),{statusCode:503});const input=await body(req),action=route.split('/').at(-1),allowed=action==='preview'?['reviewId','queueIds','updateSubject']:action==='apply'?['ticket','confirmed']:['ticket'];if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!allowed.includes(k)))throw Object.assign(new Error('Unexpected update request fields.'),{statusCode:400});const result=action==='preview'?await letterUpdates.preview(input):action==='apply'?await letterUpdates.apply(input):letterUpdates.cancel(input);sendJson(res,200,{ok:true,...result});return true;}
