// Local display helpers: no API calls, persistence or contact lookup.
export function linkedInProfileUrl(value){try{const u=new URL(String(value||''));const host=u.hostname.toLowerCase();if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.port||!(host==='linkedin.com'||host.endsWith('.linkedin.com'))||!/^\/(?:in|pub)\/[^/]+/i.test(u.pathname))return '';return u.href;}catch{return '';}}
export function createLinkedInIcon(value,name='contact',doc=document){const href=linkedInProfileUrl(value);if(!href)return null;const a=doc.createElement('a');a.href=href;a.target='_blank';a.rel='noopener noreferrer';a.className='linkedin-profile-icon';a.setAttribute('aria-label','Open LinkedIn profile for '+name);a.title='Open LinkedIn profile for '+name;const mark=doc.createElement('span');mark.textContent='in';mark.setAttribute('aria-hidden','true');a.appendChild(mark);return a;}
export function historyDate(value,{timeZone}={}){const d=new Date(value);if(!value||Number.isNaN(d.getTime()))return 'Not recorded';const p=new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'2-digit',...(timeZone?{timeZone}:{})}).formatToParts(d);return ['day','month','year'].map(k=>p.find(v=>v.type===k)?.value||'').join('-');}

// Contact-only local UI policy; no provider calls or queue/ledger mutation.
export function businessDomain(value){const v=String(value||'').trim().replace(/^@/,'').toLowerCase();if(v.length>253||!v.split('.').every(p=>p.length<=63&&/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(p))||!v.includes('.')||!/^[a-z]{2,63}$/.test(v.split('.').at(-1))||['linkedin.com','gmail.com','googlemail.com','outlook.com','hotmail.com','yahoo.com','icloud.com','example.com','example.net','example.org'].some(p=>v===p||v.endsWith('.'+p)))return '';return v;}
export function resolveEmailRow(data,edit,domain){const row={...data,...(edit||{})},origin=row.emailSource||row.source||'unknown',active=businessDomain(domain);if(active&&origin==='inferred'&&!row.verified){const match=/^([^@\s]+)@[^@\s]+$/.exec(row.email||'');if(match)row.email=match[1]+'@'+active;}row.emailSource=origin;return row;}
export function resolveEmailRows(rows,domain,edits=new Map(),keyFor=v=>v.key){const seen=new Set();return rows.flatMap(data=>{const row=resolveEmailRow(data,edits.get(keyFor(data)),domain),key=JSON.stringify([row.contactId||row.clientKey||row.key,String(row.email||'').toLowerCase()]);if(seen.has(key))return [];seen.add(key);return [{...row,source:row.emailSource}];});}
export function receiptRows(rows,result){const items=Array.isArray(result.items)?result.items:[];return rows.map(row=>{const item=items.find(v=>String(v?.email||'').toLowerCase()===String(row.email||'').toLowerCase()&&(!row.contactId||v.contactId===row.contactId));return {email:row.email||'',queueId:item?.id||'',status:item?.status||'Not returned in receipt',represented:Boolean(item)};});}
export function renderQueueReceipt(status,rows,result,doc=document){let panel=status.nextElementSibling;if(!panel?.classList?.contains('contact-queue-receipt')){panel=doc.createElement('details');panel.className='contact-queue-receipt';status.after(panel);}panel.replaceChildren();const summary=doc.createElement('summary');summary.textContent='Queue receipt — every submitted address';panel.appendChild(summary);const table=doc.createElement('table'),head=table.createTHead().insertRow();for(const text of ['Submitted address','Queue status','Queue ID']){const th=doc.createElement('th');th.textContent=text;head.appendChild(th);}const body=table.createTBody();for(const row of receiptRows(rows,result)){const tr=body.insertRow();for(const value of [row.email,row.status,row.queueId])tr.insertCell().textContent=value;}panel.appendChild(table);}
export function queueReceipt(rows,result){const added=Number(result.added||0),updated=Number(result.updated||0),duplicates=Number(result.duplicates||0),items=Array.isArray(result.items)?result.items:[],unaccounted=Math.max(0,rows.length-added-updated-duplicates,receiptRows(rows,result).filter(r=>!r.represented).length),states={};for(const item of items){const key=item?.status||'unreported';states[key]=(states[key]||0)+1;}return {submitted:rows.length,distinctAddresses:new Set(rows.map(r=>String(r.email||'').toLowerCase())).size,added,updated,duplicates,receiptItems:items.length,unaccounted,states};}
export function receiptText(r){return `${r.submitted} submitted (${r.distinctAddresses} distinct address(es)): ${r.added} new; ${r.updated} pending updated; ${r.duplicates} already represented. ${r.unaccounted} unaccounted/unverified. Receipt items: ${r.receiptItems}. States: ${Object.entries(r.states).map(([k,v])=>k+'='+v).join(', ')||'not supplied'}. Nothing sent. Existing/processed rows are not new send approvals.`;}

import {highlightPhrasePatternSource} from '../../application/cover-letter-controls.js';
import {renderLinkedRoleOpening} from '../../domain/shared/linked-role-opening.js';
function escape(value) {
  return String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;');
}
export function renderCoverLetterHtml(text = '', highlightPhrases = []) {
  const phrases = [...new Set((Array.isArray(highlightPhrases) ? highlightPhrases : [])
    .map(value => String(value || '').trim()).filter(value => value && value.length <= 120 && !/[<>\r\n{}]/.test(value)))].slice(0, 16).sort((a,b) => b.length-a.length);
  const pattern=phrases.length?new RegExp(phrases.map(highlightPhrasePatternSource).join('|'),'giu'):null;
  const highlight = line => {
    if (!pattern || /^(?:Dear\b|I am applying\b|I appreciate the convenience of ATS-based applications\b|Warm regards|Vijay DAFAL)/i.test(line)) return escape(line);
    let result = '', cursor = 0;
    for (const match of line.matchAll(pattern)) {
      const left = line[match.index-1] || '', right = line[match.index+match[0].length] || '';
      if (/[\p{L}\p{N}_]/u.test(left) || /[\p{L}\p{N}_]/u.test(right)) continue;
      result += escape(line.slice(cursor,match.index)) + `<mark data-job-aligned="true" data-highlight="true">${escape(match[0])}</mark>`;
      cursor = match.index+match[0].length;
    }
    return result+escape(line.slice(cursor));
  };
  const linked=renderLinkedRoleOpening(text,highlight);
  if(linked!==null)return linked;
  return String(text).replace(/\r\n/g, '\n').split('\n').map(line => {
    const match = line.match(/^Job advert:\s*(https?:\/\/\S+)\s*$/i);
    if (match) {
      try {
        const url = new URL(match[1]);
        if (['http:', 'https:'].includes(url.protocol)) return `Job advert: <a href="${escape(url.href)}" target="_blank" rel="noopener noreferrer">Job advert</a>`;
      } catch {}
    }
    return highlight(line);
  }).join('<br>');
}

