          emailDomain.length <= 253 &&
          labels.length >= 2 &&
          labels.every((label) =>
            label.length <= 63 &&
            /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label)
          ) &&
          /^[a-z]{2,63}$/.test(labels[labels.length - 1]) &&
