      const html = String(editor?.innerHTML || '').trim();
      const text = editorPlainText(editor);

      if (
        !navigator.clipboard ||
        !navigator.clipboard.write ||
        !window.ClipboardItem
      ) {
        return false;
      }

      try {
        await navigator.clipboard.write([
