            status.textContent = 'Only http(s) links are allowed.';
            return;
          }

          document.execCommand('createLink', false, url.href);
          status.textContent = 'Link added locally.';
        } catch {
          status.textContent = 'Enter a valid full http(s) link.';
        }

        return;
