function unzip(bytes){const files={};let offset=0;while(bytes.readUInt32LE(offset)===0x04034b50){const size=bytes.readUInt32LE(offset+18),len=bytes.readUInt16LE(offset+26),extra=bytes.readUInt16LE(offset+28),name=bytes.subarray(offset+30,offset+30+len).toString();const start=offset+30+len+extra;files[name]=bytes.subarray(start,start+size);offset=start+size;}return files;}
