test('unsafe and credential-bearing fallback URLs are not converted to hyperlinks',()=>{for(const u of ['javascript:alert(1)','https://user:pass@example.test/job']){const p=plain.replace(url,u);assert.equal(linkedOpeningParts(p),null);const h=renderCoverLetterHtml(p);assert.ok(!h.includes('<a href='));}});
