test('late imported-advert content gains a grid and section link without losing its description',async({page,workspaceApp})=>{const id=await workspaceApp.create();await page.goto(workspaceApp.url+'/applications/'+id);await page.evaluate(()=>{const section=document.createElement('section');section.className='review-section';const heading=document.createElement('h2');heading.textContent='Imported LinkedIn advert';const preview=document.createElement('div');for(const text of ['Job: Synthetic role','Advertised by: Synthetic advertiser']){const p=document.createElement('p');p.textContent=text;preview.appendChild(p);}const details=document.createElement('details'),summary=document.createElement('summary'),text=document.createElement('pre');summary.textContent='Description preview';text.textContent='Full synthetic description retained verbatim.';details.append(summary,text);preview.appendChild(details);section.append(heading,preview);document.querySelector('main').appendChild(section);});await expect(page.locator('.workspace-imported-grid')).toBeVisible();await expect(page.getByRole('navigation',{name:'Application sections'}).getByRole('link',{name:'Imported advert',exact:true})).toBeVisible();await page.locator('.workspace-imported-grid summary').click();await expect(page.locator('.workspace-imported-grid pre')).toHaveText('Full synthetic description retained verbatim.');expect(workspaceApp.paidCalls).toBe(0);});

