test('retained length-rejected proposal is reassessed locally, not accepted or regenerated',async({page,workspaceApp})=>{const r=workspaceApp.store.get('legacy'),candidate=Array.from({length:450},()=> 'delivery').join(' ');workspaceApp.store.set('legacy',{...r,rejectedRefinementProposal:{proposedDraft:candidate,lengthCheckFailed:true,letterLengthMode:'standard',warnings:['Above standard limit.']}});await page.goto(workspaceApp.url+'/applications/legacy');await page.locator('[data-rejected-quality-proposal] summary').click();await page.getByRole('button',{name:'Review retained proposal in Extended mode — no AI call'}).click();await expect(page.locator('#proposed-cover-letter')).toHaveText(candidate);await expect(page.locator('[data-letter-quality-for="proposed-cover-letter"]')).toContainText('extended');expect(workspaceApp.store.get('legacy').currentDraftPlainText).toBe(r.currentDraftPlainText);expect(workspaceApp.paidCalls).toBe(0);});
